from __future__ import annotations

from dataclasses import dataclass


class Money:
    def __init__(self, cents):
        self.cents = int(cents)

    @classmethod
    def of(cls, text):
        return cls(round(float(text) * 100))

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents

    def __add__(self, other):
        return Money(self.cents + other.cents)

    def __mul__(self, other):
        return Money(round(self.cents * other))


@dataclass
class Line:
    ref: str
    name: str
    price: Money
    qty: int = 1
    taxable: bool = True


class Invoice:
    def __init__(self, number, client, discount_percent=0, tax_rate=0):
        self.number = number
        self.client = client
        self.discount_percent = discount_percent
        self.tax_rate = tax_rate
        self.lines = []

    def add(self, line):
        self.lines.append(line)
        return self

    def taxable_amount(self):
        total = Money(0)
        for line in self.lines:
            if line.taxable:
                total = total + line.price * line.qty
        if self.discount_percent:
            total = total * (1 - self.discount_percent / 100)
        return total

    def tax(self):
        return self.taxable_amount() * self.tax_rate

    def total(self):
        untaxed = Money(0)
        for line in self.lines:
            if not line.taxable:
                untaxed = untaxed + line.price * line.qty
        return self.taxable_amount() + self.tax() + untaxed

